        out_q.append(None)
    return out_c, classes, qv, tv, pv, tc, pc, qc, tsrc

# The naive query part needs all members; easier to re-run enumeration storing
# members per class.  We re-implement run() storing everything.
def run_full(req):
    K,B,S,W,fns,tsrc,tc,pc,qc=build(req)
    natoms=len(fns); ns=len(tsrc)
    tv=[[f(c[2]) for c in tc] for f in fns]
    pv=[[f(c[2]) for c in pc] for f in fns]
    qv=[[f(c[2]) for c in qc] for f in fns]
    ntrain=len(tc); nprobe=len(pc); nquery=len(qc)
    src_of=[s for _,_,_,s in tc]
    def LT(ai,neg): return [ (v != neg) for v in tv[ai] ]
    LTM={}; LPM={}; LQM={}
    for ai in range(natoms):
        for neg in (False,True):
            LTM[(ai,neg)]=[(v!=neg) for v in tv[ai]]
            LPM[(ai,neg)]=[(v!=neg) for v in pv[ai]]
            LQM[(ai,neg)]=[(v!=neg) for v in qv[ai]]
    classes={}
    if natoms>0 and ns>0 and nprobe>0:
        import itertools
        for k in range(1,B+1):
            for atomset in itertools.combinations(range(natoms),k):
                for signs in itertools.product((False,True),repeat=k):
                    lits=list(zip(atomset,signs))
                    ok=True
                    for (ai,neg) in lits:
                        lt=LTM[(ai,neg)]
                        for s in tsrc:
                            cnt=sum(1 for i in range(ntrain) if src_of[i]==s and lt[i])
                            if cnt<S: ok=False;break
                        if not ok: break
                    if not ok: continue
                    bad=False
                    for i in range(ntrain):
                        if not any(LTM[(ai,neg)][i] for (ai,neg) in lits):
                            bad=True;break
                    if bad: continue
                    ok=True
                    for (ai,neg) in lits:
                        lt=LTM[(ai,neg)]
                        for s in tsrc:
                            cnt=0
                            for i in range(ntrain):
                                if src_of[i]!=s or not lt[i]: continue
                                good=True
                                for (aj,nj) in lits:
                                    if (aj,nj)==(ai,neg): continue
                                    if LTM[(aj,nj)][i]: good=False;break
                                if good: cnt+=1
                            if cnt<W: ok=False;break
                        if not ok: break
                    if not ok: continue
                    sig=0
                    for j in range(nprobe):
                        if any(LPM[(ai,neg)][j] for (ai,neg) in lits):
                            sig|=1<<j
                    if sig==(1<<nprobe)-1: continue
                    classes.setdefault(sig,[]).append(lits)
    hexlen=(nprobe+3)//4
    out_c=[{'signature':format(sig,'x').zfill(hexlen),'members':len(mems),
            'representative':{'or':[{'atom':a,'negated':n} for a,n in mems[0]]}}
           for sig,mems in classes.items()]
    out_q=[]
    for j in range(nquery):
        m=0;y=0
        for sig,mems in classes.items():
            truths=[any(LQM[(a,n)][j] for (a,n) in lits) for lits in mems]
            if all(not t for t in truths): m+=1
            if any(not t for t in truths): y+=1
        st='violating' if m>0 else ('ambiguous' if y>0 else 'consistent')
        out_q.append({'trace':qc[j][0],'end':qc[j][1],'must':m,'may':y,'status':st})
    return {'version':1,'classes':out_c,'queries':out_q}

def main():
    data=sys.stdin.buffer.read()
    if len(data)>MAXBYTES:
        print(json.dumps({"error":"E_LIMIT"},separators=(',',':'))); return
    try: text=data.decode('utf-8')
    except UnicodeDecodeError:
        print(json.dumps({"error":"E_JSON"},separators=(',',':'))); return
    if text[:1]=='﻿':
        print(json.dumps({"error":"E_JSON"},separators=(',',':'))); return
    try: req=parse(text)
    except JsonErr:
        print(json.dumps({"error":"E_JSON"},separators=(',',':'))); return
    try: res=run_full(req)
    except SchemaErr:
        print(json.dumps({"error":"E_SCHEMA"},separators=(',',':'))); return
    print(json.dumps(res,separators=(',',':')))

if __name__=='__main__':
    main()
